    'usage_step6' => '<strong>Tracking</strong> — Gantt, dashboards, 分析, load, リスク signals.',
    'usage_step7' => '<strong>Automation</strong> — workflow rules, SLA, webhooks, approval chains.',
    'usage_examples_heading' => 'Concrete examples',
    'usage_ex1' => '<strong>Freelancer:</strong> 顧客 リクエスト → AI analyzes → タスク 計画 → My Day → execution → 顧客 chat → done.',
